import{_ as l,l as n,o as e,c as s,v as i,p,x as t,d as r,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Negishi 方法","description":"","frontmatter":{"title":"Negishi 方法","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/negishi-map.md","filePath":"econ/negishi-map.md","lastUpdated":1789023840000}'),h={name:"econ/negishi-map.md"};function c(E,a,b,_,u,A){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="negishi-方法" tabindex="-1">Negishi 方法 <a class="header-anchor" href="#negishi-方法" aria-label="Permalink to &quot;Negishi 方法&quot;">​</a></h1><div class="epigraph"><p>给每人一个福利权重，在可行集上最大化加权效用之和，支撑价格就是候选均衡价格；再调权重直到每人预算闭合。</p><footer>—— 据 Negishi, Welfare Economics and Existence of an Equilibrium for a Competitive Economy, Metroeconomica, 1960 整理</footer></div><p><a href="/econ/smd-excess-demand">上一课</a>（Sonnenschein–Mantel–Debreu）。总体 \\(z(p)\\) 在三条公理外几乎任意，对着超额需求找零点没有免费结构。本课不重写 Debreu 的构造。缺口是换未知数：第二定理说有效配置可被价格支撑；把福利权当参数，先在配置空间里解计划问题，再用预算余额把权调到瓦尔拉斯。均衡仍可能多，但映射定义在权重单纯形上，计算与存在都可以走这条路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SMD 让 \\(p\\mapsto z(p)\\) 不驯服。Negishi 问：能否把均衡写成「某个加权福利最优，且转移为零」？给定 \\(\\lambda\\in\\Delta^{I-1}\\)，解</p> \\[\\max_x \\sum_i\\lambda_i u^i(x^i)\\quad\\text{s.t. }\\sum_i x^i\\le\\sum_i\\omega^i \\]<p>（生产经济则加 \\(Y\\)）。内点下，资源约束的乘数 \\(p(\\lambda)\\) 支撑每人的 MRS。配置 \\(x(\\lambda)\\) 一般不是禀赋下的需求：隐含的转移是 \\(T^i=p\\cdot(x^i-\\omega^i)\\)。缺口是找 \\(\\lambda^*\\) 使所有 \\(T^i=0\\)。于是福利权扮演了价格的角色——更准确：权决定支撑价格与配置，预算闭合筛选哪一组权是竞争均衡。</p><h3 id="权不是又一组市场价格" tabindex="-1">权不是又一组市场价格 <a class="header-anchor" href="#权不是又一组市场价格" aria-label="Permalink to &quot;权不是又一组市场价格&quot;">​</a></h3><p>\\(\\lambda_i\\) 是计划者放在 \\(i\\) 的效用上的数，不是 \\(p\\)。\\(p\\) 从可行约束来。把 \\(\\lambda\\) 读成「谁更有钱」会混：权更大的人在最优里边际效用被压得更低、消费通常更多，但钱是 \\(p\\cdot\\omega^i\\)，由禀赋与 \\(p(\\lambda)\\) 决定。闭合条件正是让「计划分到的」与「市场买得起的」重合。</p><p><span class="marginnote">第二定理从有效配置出发找 \\(p\\) 与转移。Negishi 把转移钉成零，反解 \\(\\lambda\\)。存在性：\\(\\lambda\\mapsto T(\\lambda)\\) 在权重单纯形上有零点，可用角谷，商品空间维数不进未知数个数——未知数是 \\(I-1\\) 个权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>映射 \\(\\Phi:\\Delta^{I-1}\\to\\mathbb{R}^{I}\\)，\\(T^i(\\lambda)=p(\\lambda)\\cdot(x^i(\\lambda)-\\omega^i)\\)。瓦尔拉斯定律使 \\(\\sum T^i=0\\)，故可看作切空间上的向量场。零点即竞争均衡。凸连续假设下 \\(x(\\lambda)\\) 凸值上半连续，\\(T\\) 有零点——与上一课存在性平行，不经过野的 \\(z(p)\\)。</p><p>计算一般均衡常用这条路：猜 \\(\\lambda\\)，解一个最优规划（比解互补的 \\(z(p)=0\\) 更稳），看预算，更新 \\(\\lambda\\)。SCARF 一类单纯形算法也可以对 \\(\\Phi\\) 做。本课不把算法细节当主干。</p>',13)),(e(),p(m,null,{default:t(()=>[d(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SMD%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9Az(p)%20%E5%87%A0%E4%B9%8E%E4%BB%BB%E6%84%8F%22%5D%20--%3E%20W%5B%22%E7%BB%99%E5%AE%9A%20%CE%BB%EF%BC%9A%E5%8A%A0%E6%9D%83%E7%A6%8F%E5%88%A9%E6%9C%80%E5%A4%A7%22%5D%0A%20%20W%20--%3E%20P%5B%22%E6%94%AF%E6%92%91%E4%BB%B7%E6%A0%BC%20p(%CE%BB)%22%5D%0A%20%20P%20--%3E%20T%5B%22%E9%A2%84%E7%AE%97%E4%BD%99%E9%A2%9D%20T(%CE%BB)%22%5D%0A%20%20T%20--%3E%20EQ%5B%22T%20%3D%200%EF%BC%9A%E7%AB%9E%E4%BA%89%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>有生产时，计划在 \\(Y\\) 上选净产出，同一套 \\(p\\) 让厂商利润最大——第一定理的逆方向在加权问题上自动满足。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「福利权当价格」：帕累托最优的一阶条件是 \\(\\lambda_i\\nabla u^i=\\mu\\)，即 MRS 对齐到同一 \\(p=\\mu\\)。这是有效的切条件。竞争还要求预算：\\(p\\cdot x^i=p\\cdot\\omega^i\\)。只动 \\(p\\) 时，\\(x\\) 沿需求走，\\(z\\) 可以乱；先强制切条件（有效），再只用 \\(I-1\\) 个自由度去满足预算，未知数从 \\(L-1\\) 个相对价格换成 \\(I-1\\) 个权。人少商品多时，这条路更短。</p><p>SMD 仍在：\\(\\Phi\\) 的零点仍可有多个，比较静态仍不必唯一。Negishi 不驯服 \\(z\\)，只避免把野函数当求解对象。</p><p><span class="marginnote">\\(\\lambda_i=0\\) 的人在计划里可以落到生存边界，对应「无权」的角点均衡。内部禀赋假设挡住某些崩塌。权重单纯形的边界要单独检查，与存在性课切立方体是同一类权宜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非凸偏好或 IRS 时加权问题的解集不必凸，\\(\\Phi\\) 失去角谷所需的凸值，存在性一起垮——不是方法的错，是经济没有均衡。不完全市场没有单一帕累托集可加权，GEI 要用约束有效的 Negishi 变体，下一课序的 Radner 再谈计划。也不要把 \\(\\lambda\\) 写成宏观的社会偏好：这里的权是计算装置，不是 Arrow 加总出来的 \\(W\\)。</p><p>下一课<a href="/econ/uniqueness-tatonnement">唯一性与试错</a>仍要对总体结构加条件；Negishi 只换了找零点的坐标系。</p><p>后课默认：竞争均衡是某组福利权下的可行最优，且隐含转移为零；权在单纯形上调整，价格是支撑乘数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMD 之后，不靠驯服 \\(z\\)，而靠加权规划加预算闭合。</li><li>\\(\\lambda\\) 选配置与支撑 \\(p\\)；\\(T(\\lambda)=0\\) 筛选均衡。</li><li>未知数个数随人数，不随商品种类。</li><li>多重均衡仍然可能；方法是换坐标，不是唯一性定理。</li><li>出处：Negishi, <em>Metroeconomica</em>, 1960。</li></ul>',11))])}const x=l(h,[["render",c]]);export{g as __pageData,x as default};
